using System.Linq;
using FluentPass.Tests.Mocks;
using FluentPass.ViewModels;
using KeePassLib;
using NUnit.Framework;

namespace FluentPass.Tests
{
    /// <summary>
    /// 内联快速密码生成（官方 PwGenerator.Generate + 宿主 AutoGeneratedPasswordsProfile）
    /// 与命令面板（QuickAccess）的检索与动作路由。
    /// </summary>
    [TestFixture, Apartment(System.Threading.ApartmentState.STA), Category("Integration")]
    public class QuickGeneratorAndQuickAccessTests
    {
        private TestPluginHost _host = null!;
        private MainViewModel _mainVm = null!;

        [SetUp]
        public void Setup()
        {
            Common.MessageService.EnableDialogs = false;
            FluentPass.Common.Loc.Instance.SetLanguagePreference("en-US"); // 命令名匹配断言需要确定语言
            _host = new TestPluginHost();

            var e1 = TestPluginHost.CreateTestEntry("GitHub Account", "octocat", "secret-pass-1", "https://github.com", "");
            var e2 = TestPluginHost.CreateTestEntry("Mail Server", "postmaster", "secret-pass-2", "imap://mail.example.com", "");
            _host.Database.RootGroup.AddEntry(e1, true);
            _host.Database.RootGroup.AddEntry(e2, true);

            _mainVm = new MainViewModel(_host);
            _mainVm.LoadGroups();
        }

        // ===== 快速生成 =====

        [Test]
        public void GenerateQuick_InEditMode_FillsDraft()
        {
            var entry = TestPluginHost.CreateTestEntry("GenEdit", "u", "", "", "");
            _host.Database.RootGroup.AddEntry(entry, true);
            var vm = new EntryDetailViewModel(entry, _host, null, () => { });
            vm.BeginEdit();
            vm.EditPassword = "";

            vm.GeneratePasswordQuick();

            Assert.That(vm.EditPassword, Is.Not.Empty, "编辑模式：生成结果应回填草稿");
            Assert.That(vm.PasswordQualityBits, Is.GreaterThan(0));
            Assert.That(entry.Strings.ReadSafe(PwDefs.PasswordField), Is.EqualTo(""), "未保存前不得写回条目");
        }

        [Test]
        public void GenerateQuick_InViewMode_UpdatesEntryWithBackup()
        {
            var entry = TestPluginHost.CreateTestEntry("GenView", "u", "old-pass", "", "");
            _host.Database.RootGroup.AddEntry(entry, true);
            var vm = new EntryDetailViewModel(entry, _host, null, () => { });

            vm.GeneratePasswordQuick();

            Assert.That(entry.Strings.ReadSafe(PwDefs.PasswordField), Is.Not.EqualTo("old-pass"));
            Assert.That(entry.Strings.ReadSafe(PwDefs.PasswordField), Is.Not.Empty);
            Assert.That(entry.History.UCount, Is.EqualTo(1u), "直接改密前必须 CreateBackup（铁律 3）");
            Assert.That(_host.Database.Modified, Is.True);
        }

        [Test]
        public void GenerateQuick_RepeatedCalls_ProduceDifferentPasswords()
        {
            var entry = TestPluginHost.CreateTestEntry("GenTwice", "u", "", "", "");
            _host.Database.RootGroup.AddEntry(entry, true);
            var vm = new EntryDetailViewModel(entry, _host, null, () => { });
            vm.BeginEdit();

            vm.GeneratePasswordQuick();
            var first = vm.EditPassword;
            vm.GeneratePasswordQuick();
            var second = vm.EditPassword;

            Assert.That(first, Is.Not.Empty);
            Assert.That(second, Is.Not.Empty);
            Assert.That(second, Is.Not.EqualTo(first));
        }

        // ===== 命令面板 =====

        [Test]
        public void QuickAccess_EmptyQuery_ShowsRecentEntriesAndCommands()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.ApplyFilter();

            Assert.That(qa.Results.Any(r => r.IsEntry), Is.True);
            Assert.That(qa.Results.Count(r => !r.IsEntry), Is.EqualTo(5), "内置命令全集");
            Assert.That(qa.SelectedResult, Is.Not.Null);
        }

        [Test]
        public void QuickAccess_QueryByTitle_FiltersEntries()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "github";

            var entryResults = qa.Results.Where(r => r.IsEntry).ToList();
            Assert.That(entryResults.Count, Is.EqualTo(1));
            Assert.That(entryResults[0].Title, Is.EqualTo("GitHub Account"));
        }

        [Test]
        public void QuickAccess_QueryByUserName_Matches()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "postmaster";

            Assert.That(qa.Results.Where(r => r.IsEntry).Single().Title, Is.EqualTo("Mail Server"));
        }

        [Test]
        public void QuickAccess_QueryByUrl_Matches()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "imap://mail.example.com";

            Assert.That(qa.Results.Where(r => r.IsEntry).Single().Title, Is.EqualTo("Mail Server"));
        }

        [Test]
        public void QuickAccess_NoMatch_ShowsCommandsOnly()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "zzz-no-such-thing";

            Assert.That(qa.Results.Any(r => r.IsEntry), Is.False);
            Assert.That(qa.Results.Count, Is.GreaterThanOrEqualTo(0));
        }

        [Test]
        public void QuickAccess_QueryMatchesCommandName()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = Loc_EN("QuickAccess_Cmd_Lock"); // "Lock database"

            var command = qa.Results.FirstOrDefault(r => !r.IsEntry);
            Assert.That(command, Is.Not.Null);
            Assert.That(command!.CommandId, Is.EqualTo("lock"));
        }

        [Test]
        public void QuickAccess_RecycleBinEntries_Excluded()
        {
            _host.Database.RecycleBinEnabled = true;
            var rb = new PwGroup(true, true, "Recycle Bin", PwIcon.TrashBin);
            _host.Database.RootGroup.AddGroup(rb, true);
            _host.Database.RecycleBinUuid = rb.Uuid;
            var trashed = TestPluginHost.CreateTestEntry("TrashedSecretItem", "u", "p", "", "");
            rb.AddEntry(trashed, true);
            _mainVm.RefreshDatabaseState();

            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "TrashedSecretItem";

            Assert.That(qa.Results.Any(r => r.IsEntry), Is.False, "回收站条目不应进入命令面板（与浏览口径一致）");
        }

        [Test]
        public void QuickAccess_ExecuteEntryCopyPassword_CopiesToClipboard()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "GitHub Account";
            var target = qa.Results.First(r => r.IsEntry);

            qa.ExecuteEntryCopyPassword(target);

            Assert.That(GetClipboardTextWithRetry("secret-pass-1"), Is.EqualTo("secret-pass-1"));
        }

        [Test]
        public void QuickAccess_ExecuteEntryCopyUsername_CopiesToClipboard()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "GitHub Account";
            var target = qa.Results.First(r => r.IsEntry);

            qa.ExecuteEntryCopyUsername(target);

            Assert.That(GetClipboardTextWithRetry("octocat"), Is.EqualTo("octocat"));
        }

        [Test]
        public void QuickAccess_ExecuteCommand_Lock_UpdatesStatus()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.ApplyFilter();
            var lockCommand = qa.Results.First(r => r.CommandId == "lock");

            qa.ExecuteCommand(lockCommand);

            Assert.That(_mainVm.StatusMessage, Is.EqualTo(FluentPass.Common.Loc.Get("Status_Locked")));
        }

        [Test]
        public void QuickAccess_ExecuteDefault_Entry_CopiesPassword()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            qa.SearchText = "Mail Server";
            var target = qa.Results.First(r => r.IsEntry);

            qa.ExecuteDefault(target);

            Assert.That(GetClipboardTextWithRetry("secret-pass-2"), Is.EqualTo("secret-pass-2"));
        }

        /// <summary>
        /// OLE 剪贴板写入存在延迟渲染/flush 时序：前一个测试的写入可能尚未对新读者可见。
        /// 轮询至多 2 秒，避免偶发的“读到上一次写入”竞态（实测于 2.57.1/2.61.1 双宿主）。
        /// </summary>
        private static string GetClipboardTextWithRetry(string expected)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            string last = string.Empty;
            while (sw.ElapsedMilliseconds < 2000)
            {
                last = System.Windows.Forms.Clipboard.GetText();
                if (last == expected) return last;
                System.Threading.Thread.Sleep(50);
            }
            return last;
        }

        [Test]
        public void QuickAccess_ExecuteNull_NoThrow()
        {
            var qa = new QuickAccessViewModel(_host, _mainVm);
            Assert.That(() => qa.ExecuteDefault(null), Throws.Nothing);
            Assert.That(() => qa.ExecuteCommand(null), Throws.Nothing);
            Assert.That(() => qa.ExecuteEntryCopyPassword(null), Throws.Nothing);
            Assert.That(() => qa.ExecuteEntryAutoType(null), Throws.Nothing);
        }

        private static string Loc_EN(string key)
        {
            return FluentPass.Common.TranslationStore.Get("en-US", key);
        }
    }
}
